<script>
	let text = $state('');

	const stats = $derived.by(() => {
		const words = text.trim().split(/\s+/).filter(Boolean);
		const wordCount = words.length;
		const charCount = text.length;
		const isLong = wordCount > 15;
		return { wordCount, charCount, isLong };
	});

	function clear() {
		text = '';
	}
</script>

<div>
	<input data-testid="text-input" type="text" bind:value={text} />
	<button data-testid="clear-button" on:click={clear}>Clear</button>
	<div>
		<p data-testid="word-count">Words: {stats.wordCount}</p>
		<p data-testid="char-count">Characters: {stats.charCount}</p>
		<p data-testid="length-indicator">Status: {stats.isLong ? 'Long text' : 'Short text'}</p>
	</div>
</div>
```

